from kivy.app import App
from kivy.uix.button import Button
from kivy.uix.gridlayout import GridLayout
from kivy.uix.behaviors import FocusBehavior
from kivy.uix.behaviors.compoundselection import CompoundSelectionBehavior
from kivy.core.window import Window
from kivy.properties import ListProperty
from kivy.clock import Clock

class SelectableGrid(FocusBehavior, CompoundSelectionBehavior, GridLayout):
    selected_color = ListProperty([0.2, 0.6, 1, 1])
    normal_color = ListProperty([1, 1, 1, 1])

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self._number_buffer = ''
        self._number_buffer_ev = None
        self.multiselect = True
        self.touch_deselect_last = False
        Window.bind(on_key_down=self._on_key_down, on_key_up=self._on_key_up)
        self.bind(selected_nodes=self.on_selection_change)

    def _on_key_down(self, window, key, scancode, codepoint, modifiers):
        if codepoint and codepoint.isdigit():
            self._number_buffer += codepoint
            if self._number_buffer_ev:
                self._number_buffer_ev.cancel()
            self._number_buffer_ev = Clock.schedule_once(self._process_number_buffer, 0.7)
        elif key == 273:  # up
            self.select_node_by_offset(-self.cols)
        elif key == 274:  # down
            self.select_node_by_offset(self.cols)
        elif key == 275:  # right
            self.select_node_by_offset(1)
        elif key == 276:  # left
            self.select_node_by_offset(-1)
        elif key == 32:  # space
            self.toggle_node_selection(self._last_selected_node())
        elif key == 27:  # escape
            self.clear_selection()
        return True

    def _on_key_up(self, window, key, scancode):
        return True

    def _process_number_buffer(self, dt):
        if self._number_buffer:
            idx = int(self._number_buffer) - 1
            if 0 <= idx < len(self.children):
                node = self.children[::-1][idx]
                self.select_node(node)
            self._number_buffer = ''

    def select_node_by_offset(self, offset):
        if not self.selected_nodes:
            idx = 0
        else:
            idx = self.children[::-1].index(self._last_selected_node())
            idx = max(0, min(len(self.children) - 1, idx + offset))
        node = self.children[::-1][idx]
        self.select_node(node)

    def select_node(self, node):
        if node not in self.selected_nodes:
            self.select_with_touch(node, None)
        else:
            self.deselect_node(node)

    def deselect_node(self, node):
        if node in self.selected_nodes:
            self.deselect_node(node)

    def toggle_node_selection(self, node):
        if node in self.selected_nodes:
            self.deselect_node(node)
        else:
            self.select_node(node)

    def _last_selected_node(self):
        if self.selected_nodes:
            return self.selected_nodes[-1]
        return None

    def select_with_touch(self, node, touch=None):
        super().select_with_touch(node, touch)
        self.update_node_colors()

    def deselect_node(self, node):
        super().deselect_node(node)
        self.update_node_colors()

    def clear_selection(self):
        super().clear_selection()
        self.update_node_colors()

    def update_node_colors(self):
        for child in self.children:
            if child in self.selected_nodes:
                child.background_color = self.selected_color
            else:
                child.background_color = self.normal_color

    def on_selection_change(self, *args):
        print("Selected nodes:", [btn.text for btn in self.selected_nodes])
        self.update_node_colors()

    def on_touch_down(self, touch):
        if not self.collide_point(*touch.pos):
            return super().on_touch_down(touch)
        for child in self.children:
            if child.collide_point(*touch.pos):
                self.select_with_touch(child, touch)
                return True
        return super().on_touch_down(touch)

    def on_touch_up(self, touch):
        return super().on_touch_up(touch)

class TestApp(App):
    def build(self):
        grid = SelectableGrid(cols=8, rows=5, spacing=5, padding=5, size_hint=(1, 1))
        for i in range(1, 41):
            btn = Button(text=str(i), background_color=[1, 1, 1, 1])
            btn.bind(on_touch_down=grid.on_touch_down)
            grid.add_widget(btn)
        return grid

if __name__ == '__main__':
    TestApp().run()
